import org.codehaus.plexus.components.io.attributes.SymlinkUtils;
import org.codehaus.plexus.logging.AbstractLogEnabled;
import org.codehaus.plexus.util.FileUtils;
import org.codehaus.plexus.util.IOUtil;
import org.codehaus.plexus.util.StringUtils;

public abstract class AbstractUnArchiver extends AbstractLogEnabled implements UnArchiver, FinalizerEnabled {

    private boolean overwrite = true;
    private boolean ignorePermissions = false;

    // other methods

    /**
     * Extracts a single entry from the archive into the target directory.
     *
     * <p>This method now performs strict validation of {@code entryName} to protect
     * against the Zip‑Slip vulnerability. The resolved file path is canonicalized
     * and verified to reside within {@code dir}. Any attempt to write outside the
     * intended extraction directory results in an {@link ArchiverException}.
     *
     * @param srcF              the source file (unused in this implementation)
     * @param dir               the target extraction directory
     * @param compressedInputStream the input stream containing the compressed data
     * @param entryName         the name of the entry within the archive
     * @param entryDate         the modification time of the entry
     * @param isDirectory       whether the entry represents a directory
     * @param mode              the POSIX permission mode (may be {@code null})
     * @param symlinkDestination the target of a symbolic link (may be {@code null})
     * @throws IOException      if an I/O error occurs
     * @throws ArchiverException if the entry name is invalid or extraction fails
     */
    protected void extractFile(final File srcF,
                               final File dir,
                               final InputStream compressedInputStream,
                               final String entryName,
                               final Date entryDate,
                               final boolean isDirectory,
                               final Integer mode,
                               String symlinkDestination) throws IOException, ArchiverException {

        // Basic sanity checks
        if (entryName == null || entryName.isEmpty()) {
            throw new ArchiverException("Entry name cannot be null or empty");
        }

        // Resolve the target file and canonicalize both paths
        final File canonicalDir = dir.getCanonicalFile();
        final File resolved = new File(dir, entryName).getCanonicalFile();

        // Ensure the resolved path is strictly within the target directory
        final String canonicalDirPath = canonicalDir.getPath() + File.separator;
        if (!resolved.getPath().startsWith(canonicalDirPath)) {
            throw new ArchiverException(
                    "Entry '" + entryName + "' resolves to a location outside the target directory");
        }

        try {
            // Skip extraction if the file already exists and is newer
            if (!isOverwrite() && resolved.exists() && (resolved.lastModified() >= entryDate.getTime())) {
                return;
            }

            // Create parent directories if necessary
            final File parent = resolved.getParentFile();
            if (parent != null) {
                parent.mkdirs();
            }

            if (!StringUtils.isEmpty(symlinkDestination)) {
                // Resolve symlink target and ensure it stays within the extraction directory
                final File symlinkTarget = new File(symlinkDestination).getCanonicalFile();
                if (!symlinkTarget.getPath().startsWith(canonicalDirPath)) {
                    throw new ArchiverException(
                            "Symlink destination '" + symlinkDestination + "' is outside the target directory");
                }
                SymlinkUtils.createSymbolicLink(resolved, symlinkTarget);
            } else if (isDirectory) {
                resolved.mkdirs();
            } else {
                // Write the file contents
                try (OutputStream out = new FileOutputStream(resolved)) {
                    IOUtil.copy(compressedInputStream, out);
                }
            }

            // Preserve the original modification time
            resolved.setLastModified(entryDate.getTime());

            // Apply permissions if requested
            if (!isIgnorePermissions() && mode != null && !isDirectory) {
                ArchiveEntryUtils.chmod(resolved, mode);
            }
        } catch (final FileNotFoundException ex) {
            getLogger().warn("Unable to expand to file " + resolved.getPath(), ex);
        }
    }

    // other methods

    @Override
    public boolean isIgnorePermissions() {
        return ignorePermissions;
    }

    @Override
    public boolean isOverwrite() {
        return overwrite;
    }

}
