    /**
     * Sanitises strings that may contain sensitive information such as tokens or
     * authorisation values. Any substring matching {@code token=...} or
     * {@code authorization=...} will have its value replaced with {@code ***}.
     */
    private static String sanitize(String input) {
        if (input == null) {
            return null;
        }
        // Mask common token/authorization patterns
        Pattern pattern = Pattern.compile("(token|authorization)=\\S+");
        return pattern.matcher(input).replaceAll("$1=***");
    }

    @SuppressWarnings({ "unchecked", "rawtypes" })
    @Override
    public boolean start() throws Exception {
