public class URIBuilder {

    // other methods

    /**
     * Normalizes a URI path by ensuring it starts with a single leading slash
     * and removing any additional leading slashes. Trailing slashes are preserved.
     *
     * @param path the original path component (may be {@code null})
     * @return a normalized path, or {@code null} if the input was {@code null}
     */
    private static String normalizePath(final String path) {
        if (path == null) {
            return null;
        }

        // Skip all leading '/' characters
        int i = 0;
        while (i < path.length() && path.charAt(i) == '/') {
            i++;
        }

        // If the entire string was slashes, return a single '/'
        if (i == path.length()) {
            return "/";
        }

        // Substring after the leading slashes
        String trimmed = path.substring(i);

        // Prepend a single '/' to guarantee a proper path component
        return "/" + trimmed;
