/**
 * Represents a PDF COSArray.  The implementation focuses on safety and
 * defensiveness when converting the array to primitive types.
 */
public class COSArray extends COSBase implements Iterable<COSBase>, COSUpdateInfo {

    /** Holds the elements of this COSArray. */
    private final List<COSBase> objects = new ArrayList<>();

    /* --------------------------------------------------------------------- */
    /* Configuration constants                                               */
    /* --------------------------------------------------------------------- */

    /**
     * Maximum number of elements that {@link #toFloatArray()} will process.
     * This protects against denial‑of‑service attacks caused by very large
     * arrays or maliciously crafted PDFs.
     */
    private static final int MAX_ARRAY_ELEMENTS = 10_000;

    /* --------------------------------------------------------------------- */
    /* Public API                                                             */
    /* --------------------------------------------------------------------- */

    /**
