import java.nio.ByteBuffer;
import java.nio.CharBuffer;
import java.nio.charset.CharsetEncoder;
import java.nio.charset.CoderResult;

class NioZipEncoding implements ZipEncoding, CharsetAccessor {

    // other methods

    @Override
    public ByteBuffer encode(final String name) {
        final CharsetEncoder enc = newEncoder();
        final CharBuffer cb = CharBuffer.wrap(name);
        ByteBuffer out = ByteBuffer.allocate(
                estimateInitialBufferSize(enc, cb.remaining()));

        final int MAX_RETRY = 10;
        int retryCount = 0;

        while (cb.remaining() > 0) {
            int oldPos = cb.position();

            CoderResult res = enc.encode(cb, out, false);

            if (res.isUnderflow()) {
                break;
            }

            if (res.isOverflow()) {
                int inc = estimateIncrementalEncodingSize(enc, cb.remaining());
                out = ZipEncodingHelper.growBufferBy(out, inc);
                continue;
            }

            if (res.isError()) {
                /* Ensure that the loop makes progress.  If the encoder
                 * reports an error but the CharBuffer position has not
                 * advanced, consume at least one character and write the
                 * encoder's replacement bytes.  This prevents an
                 * infinite loop when the input contains characters that
                 * cannot be encoded. */
                if (cb.position() == oldPos) {
                    if (cb.remaining() > 0) {
                        byte[] repl = enc.replacement();
                        if (out.remaining() < repl.length) {
                            out = ZipEncodingHelper.growBufferBy(out,
                                    repl.length - out.remaining());
                        }
                        out.put(repl);
                        cb.position(cb.position() + 1);
                        retryCount = 0;
                        continue;
                    }
                }

                /* Handle unmappable or malformed input by consuming the
                 * offending characters and writing the replacement. */
                if (res.isUnmappable() || res.isMalformed()) {
                    int len = res.length();
                    if (len <= 0) {
                        len = 1; // safety fallback
                    }
                    byte[] repl = enc.replacement();
                    if (out.remaining() < repl.length) {
                        out = ZipEncodingHelper.growBufferBy(out,
                                repl.length - out.remaining());
                    }
                    out.put(repl);
                    cb.position(cb.position() + len);
                    retryCount = 0;
                    continue;
                }

                /* Any other error is unexpected – propagate it. */
                res.throwException();
            }

            /* Reset retry counter on successful progress. */
            if (cb.position() != oldPos) {
                retryCount = 0;
            } else {
                /* No progress – increment retry counter and abort if it
                 * exceeds the threshold. */
                retryCount++;
                if (retryCount > MAX_RETRY) {
                    throw new IllegalStateException(
                            "Encoding stalled – possible infinite loop detected");
                }
            }
        }

        /* Final flush of the encoder. */
        enc.encode(cb, out, true);

        out.limit(out.position());
        out.rewind();
        return out;
    }

