public class Expander {

    // other methods

    /**
     * Safely extracts archive entries into {@code targetDirectory}.  The method
     * performs rigorous validation of each entry name to prevent path‑traversal
     * attacks and ensures that all created files reside strictly within the
     * target directory.
     *
     * @param supplier        supplies archive entries to extract
     * @param writer          writes entry data to an output stream
     * @param targetDirectory the directory into which entries will be extracted
     * @throws IOException if extraction fails or a malicious entry is detected
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the canonical path of the target directory once.
        final String targetDirCanonical = targetDirectory.getCanonicalPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {

            final String entryName = nextEntry.getName();

            /* ------------------------------------------------------------------
             * 1. Basic sanity checks on the entry name
             * ------------------------------------------------------------------ */
            if (entryName == null || entryName.isEmpty()) {
                throw new IOException("Archive entry has an empty name");
            }

            // Reject absolute paths (Unix or Windows)
            if (entryName.startsWith("/") ||
                entryName.startsWith("\\") ||
                entryName.matches("^[a-zA-Z]:.*")) {
                throw new IOException("Absolute path entry not allowed: " + entryName);
            }

            // Reject any component that attempts to traverse upwards
            if (entryName.contains("..")) {
                throw new IOException("Path traversal detected in entry: " + entryName);
            }

            /* ------------------------------------------------------------------
             * 2. Construct the destination file and verify containment
             * ------------------------------------------------------------------ */
            final File destFile = new File(targetDirectory, entryName);
            final String destCanonical = destFile.getCanonicalPath();

            if (!destCanonical.startsWith(targetDirCanonical)) {
                throw new IOException(
                    "Entry '" + entryName + "' would resolve outside of "
                    + targetDirectory.getAbsolutePath());
            }

            /* ------------------------------------------------------------------
             * 3. Create directories or write file data
             * ------------------------------------------------------------------ */
            if (nextEntry.isDirectory()) {
                if (!destFile.isDirectory() && !destFile.mkdirs()) {
                    throw new IOException("Failed to create directory: " + destFile);
                }
            } else {
                final File parent = destFile.getParentFile();
                if (!parent.isDirectory() && !parent.mkdirs()) {
                    throw new IOException("Failed to create directory: " + parent);
                }

                try (OutputStream out = Files.newOutputStream(destFile.toPath())) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            // Proceed to the next entry
            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods

}
