    /* --------------------------------------------------------------------- */
    /* Whitelist of safe component types                                    */
    /* --------------------------------------------------------------------- */

    private static final Set<Class<?>> ALLOWED_COMPONENT_TYPES;

    static {
        Set<Class<?>> tmp = new HashSet<>();
        tmp.add(String.class);
        tmp.add(Integer.class);
        tmp.add(Long.class);
        tmp.add(Short.class);
        tmp.add(Byte.class);
        tmp.add(Float.class);
        tmp.add(Double.class);
        tmp.add(Boolean.class);
        tmp.add(Character.class);
        tmp.add(BigDecimal.class);
        tmp.add(BigInteger.class);
        tmp.add(Date.class);
        tmp.add(java.sql.Date.class);
        tmp.add(Timestamp.class);
        tmp.add(java.time.LocalDate.class);
        tmp.add(java.time.LocalDateTime.class);
        tmp.add(java.time.Instant.class);
        ALLOWED_COMPONENT_TYPES = Collections.unmodifiableSet(tmp);
