        try {
            parser.parseArray(componentClass, array, fieldName);
        } catch (Exception e) {
            throw new IllegalArgumentException("Failed to parse JSON array", e);
        }

        return (T) toObjectArray(parser, componentClass, array);
    }

    /* --------------------------------------------------------------------- */
    /* Helper method to convert JSONArray to a typed array                  */
    /* --------------------------------------------------------------------- */

    private <T> T toObjectArray(DefaultJSONParser parser, Class<?> componentType, JSONArray array) {
        int size = array.size();
        Object result = java.lang.reflect.Array.newInstance(componentType, size);
        for (int i = 0; i < size; ++i) {
            Object val = array.get(i);
            java.lang.reflect.Array.set(result, i, val);
        }
        return (T) result;
    }

    /* --------------------------------------------------------------------- */
    /* Other methods omitted for brevity                                     */
    /* --------------------------------------------------------------------- */
}
