    /**
     * Creates a secure {@link XMLStreamReader} that protects against XXE attacks.
     *
     * <p>The method configures the {@link XMLInputFactory} to:
     * <ul>
     *   <li>Disable DTD support ({@code SUPPORT_DTD = false})</li>
     *   <li>Disallow external entity resolution ({@code IS_SUPPORTING_EXTERNAL_ENTITIES = false})</li>
     *   <li>Enable namespace awareness ({@code IS_NAMESPACE_AWARE = true})</li>
     *   <li>Coalesce adjacent character data and replace entity references for consistency</li>
     * </ul>
     * These settings ensure that the parser cannot load external resources or process
     * potentially malicious DTDs, mitigating XXE vulnerabilities while preserving
     * normal XML parsing functionality.</p>
     *
     * @param inputStream the raw XML input stream
     * @return a configured {@link XMLStreamReader}
     * @throws XMLStreamException if the XML cannot be parsed
     * @throws IOException if an I/O error occurs
     */
    final static private XMLStreamReader createXMLStreamReader(InputStream inputStream)
            throws XMLStreamException, IOException {

        if (inputStream == null) {
            throw new IllegalArgumentException("inputStream must not be null");
        }

        XMLInputFactory factory = XMLInputFactory.newInstance();

        // Disable DTDs and external entities to prevent XXE attacks
        factory.setProperty(XMLInputFactory.SUPPORT_DTD, Boolean.FALSE);
        factory.setProperty(XMLInputFactory.IS_SUPPORTING_EXTERNAL_ENTITIES, Boolean.FALSE);

        // Enable namespace awareness for standard XML processing
        factory.setProperty(XMLInputFactory.IS_NAMESPACE_AWARE, Boolean.TRUE);

        // Optional: disable validation to avoid unnecessary overhead
        factory.setProperty(XMLInputFactory.IS_VALIDATING, Boolean.FALSE);

        // Preserve original behavior regarding coalescing and entity replacement
        factory.setProperty(XMLInputFactory.IS_COALESCING, Boolean.TRUE);
        factory.setProperty(XMLInputFactory.IS_REPLACING_ENTITY_REFERENCES, Boolean.TRUE);

        return factory.createXMLStreamReader(wrapPrefixRemovingInputStream(inputStream));
    }

